@Aspect
@Component
@Order(1)
public class SecurityAspect {
    @Around("@annotation(Secured)")
    public Object enforceSecurity(ProceedingJoinPoint pjp) throws Throwable {
        // Executes first (outermost layer)
        validateToken();
        return pjp.proceed();
    }
}

@Aspect
@Component
@Order(2)
public class TransactionAspect {
    @Around("@annotation(Transactional)")
    public Object manageTransaction(ProceedingJoinPoint pjp) throws Throwable {
        // Executes second (nested inside SecurityAspect)
        TransactionStatus status = startTx();
        try {
            Object result = pjp.proceed();
            commitTx(status);
            return result;
        } catch (Exception e) {
            rollbackTx(status);
            throw e;
        }
    }
}
